import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { useSettingsStore } from '@/store/settingsStore';

/** Generated by scripts/generateSounds.ts. */
const SOURCES = {
  exit: require('../../assets/sounds/exit.wav'),
  blocked: require('../../assets/sounds/blocked.wav'),
  win: require('../../assets/sounds/win.wav'),
  hint: require('../../assets/sounds/hint.wav'),
  tap: require('../../assets/sounds/tap.wav'),
} as const;

export type SoundName = keyof typeof SOURCES;

let players: Record<SoundName, AudioPlayer> | null = null;

/** Creates one player per effect. Safe to call repeatedly; the first call does the work. */
export function preloadSounds(): void {
  if (players) return;
  // Short effects: never take audio focus from the player's music or podcasts.
  setAudioModeAsync({ interruptionMode: 'mixWithOthers', playsInSilentMode: false }).catch(() => {});
  players = Object.fromEntries(
    Object.entries(SOURCES).map(([name, source]) => [name, createAudioPlayer(source)]),
  ) as Record<SoundName, AudioPlayer>;
}

/** Plays an effect from the start, if the Sound setting is on. Never throws. */
export function playSound(name: SoundName): void {
  if (!useSettingsStore.getState().soundEnabled) return;
  try {
    preloadSounds();
    const player = players![name];
    player.seekTo(0).catch(() => {});
    player.play();
  } catch {
    // Audio is decoration; a failed effect must never break a tap.
  }
}
